const fs=require('fs'),path=require('path'),http=require('http'),crypto=require('crypto');
const {chromium}=require('playwright');
const root=path.resolve(__dirname,'..'),manifest=JSON.parse(fs.readFileSync(path.join(root,'data/coupang-week-20261126-manifest.json'),'utf8'));
if(manifest.length!==7)throw Error('Expected seven complete articles');
for(const x of manifest){const html=fs.readFileSync(path.join(root,x.source),'utf8'),schema=JSON.parse(html.match(/<script type="application\/ld\+json">(.*?)<\/script>/s)[1]);if(schema['@graph'].length!==3||schema['@graph'][0].mainEntityOfPage!==x.url||schema['@graph'][0].datePublished!==x.date+'T12:10:00+09:00')throw Error('Invalid metadata');const images=[...html.matchAll(/<figure[^>]*><img src="([^"]+)"/g)].map(m=>crypto.createHash('sha256').update(fs.readFileSync(path.join(root,m[1]))).digest('hex'));if(images.length!==2||new Set(images).size!==2)throw Error('Repeated body image');if(fs.existsSync(path.join(root,x.target)))throw Error('Published early');}
const server=http.createServer((req,res)=>{const route=decodeURIComponent(new URL(req.url,'http://localhost').pathname),file=path.resolve(root,'.'+route);if(!/^\/(assets\/|\.publication\/articles\/)/.test(route)||!file.startsWith(root+path.sep)||!fs.existsSync(file)||!fs.statSync(file).isFile()){res.writeHead(404);return res.end();}res.setHeader('Content-Type',({'.html':'text/html; charset=utf-8','.css':'text/css','.jpg':'image/jpeg','.webp':'image/webp','.png':'image/png'})[path.extname(file)]||'application/octet-stream');res.end(fs.readFileSync(file));});
(async()=>{let browser;try{await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port;browser=await chromium.launch({headless:true,executablePath:'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe'});const page=await browser.newPage();await page.route('**/*',r=>r.request().url().startsWith(origin+'/')?r.continue():r.abort());const checks=[];
 for(const item of manifest)for(const width of [360,390,1440]){await page.setViewportSize({width,height:1000});await page.goto(origin+'/'+item.source,{waitUntil:'networkidle'});await page.locator('article img').evaluateAll(a=>a.forEach(i=>i.loading='eager'));await page.locator('article img').evaluateAll(a=>Promise.all(a.map(i=>i.decode())));
 const stats=await page.evaluate(()=>{const a=document.querySelector('article'),cards=[...a.querySelectorAll('.affiliate-card')];return {overflow:document.documentElement.scrollWidth>innerWidth+1,width:a.getBoundingClientRect().width,cards:cards.length,links:cards.every(c=>new URL(c.href).hostname==='link.coupang.com'&&c.rel.includes('sponsored')),images:[...a.querySelectorAll('img')].every(i=>{const c=document.createElement('canvas');c.width=c.height=10;const ctx=c.getContext('2d');ctx.drawImage(i,0,0,10,10);return i.naturalWidth>0&&new Set(ctx.getImageData(0,0,10,10).data).size>8;}),photoSize:[...a.querySelectorAll('figure img')].every(i=>i.getBoundingClientRect().width<=640&&i.getBoundingClientRect().height<=441),buttons:[...a.querySelectorAll('.affiliate-card__button')].every(i=>i.getBoundingClientRect().height>=56&&parseFloat(getComputedStyle(i).fontSize)>=18),faq:a.querySelectorAll('#faq h3').length};});
 if(stats.overflow||stats.width>930||stats.cards!==4||!stats.links||!stats.images||!stats.photoSize||!stats.buttons||stats.faq<5)throw Error(JSON.stringify({title:item.title,width,stats}));checks.push({title:item.title,viewport:width,...stats});
 if(manifest.indexOf(item)===0){for(const i of await page.locator('article img').all()){await i.scrollIntoViewIfNeeded();await i.evaluate(i=>i.decode());}await page.evaluate(()=>scrollTo(0,0));await page.screenshot({path:path.join(root,`logs/cloud-week-20261126-${width}.png`),fullPage:true});if(width===390)await page.locator('.affiliate-card').first().screenshot({path:path.join(root,'logs/cloud-week-20261126-card.png')});}
 }
 fs.writeFileSync(path.join(root,'logs/cloud-week-20261126-qa.json'),JSON.stringify({articles:7,checks:checks.length,failures:0,results:checks},null,2));console.log(JSON.stringify({articles:7,checks:checks.length,failures:0}));
 }finally{if(browser)await browser.close();await new Promise(r=>server.close(r));}})().catch(e=>{console.error(e.message);process.exitCode=1});
